const base=`.ref-demo{width:min(460px,100%);color:var(--text);font-family:system-ui,sans-serif}.ref-card{background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:24px}.ref-row{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.ref-kicker{font:9px ui-monospace,monospace;letter-spacing:.14em;color:var(--muted);text-transform:uppercase}.ref-demo h2{font-size:clamp(22px,5vw,34px);line-height:1.05;letter-spacing:-.05em;font-weight:500;margin:16px 0}.ref-demo p{font-size:12px;line-height:1.6;color:var(--muted)}.ref-button{border:1px solid var(--border);border-radius:8px;background:var(--surface-2);color:var(--text);padding:9px 13px;font-size:11px;min-height:34px}.ref-primary{background:var(--accent);color:var(--on-accent)}.ref-status{display:block;min-height:18px;font-size:11px;color:var(--muted);margin-top:16px}.ref-demo input{color:var(--text);background:var(--surface);border:1px solid var(--border);border-radius:7px;padding:9px;max-width:100%}.ref-demo :focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:360px){.ref-card{padding:18px}}`;
